void itoa(int num, char *str) {
    if (num == 0) {
        *str = '\0';
        return;
    }
    int sign = 1;
    if (num < 0) {
        sign = -1;
        num = -num;
    }
    int len = 0;
    while (num!= 0) {
        str[len++] = (num % 10) + '0';
        num /= 10;
    }
    if (sign == -1) {
        str[len++] = '-';
    }
    while (len < MAX_BUFFER_LEN - 1 && len > 0) {
        str[len++] ='';
    }
    str[len] = '\0';
}

