void log_message(const char *message, char *buffer) {
    // Check if the buffer is not NULL
    if (buffer == NULL) {
        // If the buffer is NULL, print the message to the console
        printf("%s\n", message);
    } else {
        // Calculate the remaining space in the buffer
        int remaining_space = BUFFER_SIZE - strlen(buffer);

        // If there's enough space, write the message to the buffer
        if (remaining_space > strlen(message)) {
            // Copy the message to the buffer
            strncpy(buffer, message, BUFFER_SIZE);
            buffer[BUFFER_SIZE - 1] = '\0';  // Ensure the string is null-terminated
        } else {
            // If there's not enough space, print the message to the console
            printf("%s\n", message);
        }
    }
}
