int parse_csv_line(const char *line, char fields[][MAX_FIELD_LEN], int max_fields) {
    char *token;
    char *saveptr;
    int num_fields = 0;
    int i = 0;

    token = strtok_r(line, ",", &saveptr);
    while (token!= NULL && num_fields < max_fields) {
        if (num_fields >= MAX_FIELDS) {
            fprintf(stderr, "Error: Too many fields in line\n");
            return num_fields;
        }
        strcpy(fields[num_fields], token);
        num_fields++;
        token = strtok_r(NULL, ",", &saveptr);
    }

    if (num_fields < max_fields) {
        for (i = num_fields; i < max_fields; i++) {
            fields[i][0] = '\0';
        }
    }

    return num_fields;
}
